function App() {
  const [page, setPage] = useState('Overview');
  const [count, setCount] = useState(0); // lives in the 'layout'
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <header style={{ borderBottom: '1px solid #ccc', paddingBottom: 8 }}>
        <b>Dashboard layout</b> — persistent count: {count}
        <button style={{ marginLeft: 8 }} onClick={() => setCount(c => c + 1)}>+1</button>
      </header>
      <nav style={{ margin: '8px 0' }}>
        {['Overview', 'Reports'].map(p => (
          <button key={p} onClick={() => setPage(p)} style={{ marginRight: 8 }}>{p}</button>
        ))}
      </nav>
      <main>Page content: {page}</main>
    </div>
  );
}

