solution.code:
function App() {
  const map = {
    'getStaticProps': 'await a cached fetch in an async Server Component (SSG)',
    'getServerSideProps': "await fetch(url, { cache: 'no-store' }) or export const dynamic = 'force-dynamic' (SSR)",
    '_app.tsx / _document.tsx': 'app/layout.tsx (root layout with <html><body>)',
    'manual loading spinner': 'loading.tsx convention (automatic Suspense fallback)',
  };
  return (
    <ul style={{ fontFamily: 'system-ui', padding: 16 }}>
      {Object.entries(map).map(([k, v]) => <li key={k}><b>{k}:</b> {v}</li>)}
    </ul>
  );
}

