// app/counter/page.tsx — a Server Component by default (NO 'use client')
// Using a hook here is the bug: hooks need a Client Component.
function App() {
  const [count, setCount] = useState(0); // ❌ not allowed in a Server Component
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <button onClick={() => setCount(c => c + 1)}>Count: {count}</button>
    </div>
  );
}

solution.code:
// app/counter/page.tsx
// 'use client'  <-- add this line at the very top of the file
function App() {
  const [count, setCount] = useState(0); // ✓ now in a Client Component
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <button onClick={() => setCount(c => c + 1)}>Count: {count}</button>
    </div>
  );
}

// BEFORE — pages/products.tsx (Pages Router)
export async function getServerSideProps() {
  const products = await fetch('https://api/products').then(r => r.json());
  return { props: { products } };
}
export default function Products({ products }: { products: any[] }) {
  return <ul>{products.map(p => <li key={p.id}>{p.name}</li>)}</ul>;
}

// AFTER — app/products/page.tsx (App Router)
export default async function Products() {
  const products = await fetch('https://api/products', { cache: 'no-store' }).then(r => r.json());
  return <ul>{products.map((p: any) => <li key={p.id}>{p.name}</li>)}</ul>;
}
